import { test, expect } from '@playwright/test';

test.describe('Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual URL of the form
  });

  test('should highlight required fields when submitting an empty form', async ({ page }) => {
    await page.getByRole('button', { name: 'Submit' }).click();

    const requiredField1 = page.getByLabel('Field Label 1'); // Replace with actual label
    const requiredField2 = page.getByLabel('Field Label 2'); // Replace with actual label

    await expect(requiredField1).toHaveCSS('border-color', 'rgb(255, 0, 0)'); // Assuming red indicates required
    await expect(requiredField2).toHaveCSS('border-color', 'rgb(255, 0, 0)');
  });

  test('should not highlight fields if they are filled', async ({ page }) => {
    await page.getByLabel('Field Label 1').fill('Some input'); // Replace with actual label
    await page.getByLabel('Field Label 2').fill('Another input'); // Replace with actual label
    await page.getByRole('button', { name: 'Submit' }).click();

    const requiredField1 = page.getByLabel('Field Label 1');
    const requiredField2 = page.getByLabel('Field Label 2');

    await expect(requiredField1).not.toHaveCSS('border-color', 'rgb(255, 0, 0)');
    await expect(requiredField2).not.toHaveCSS('border-color', 'rgb(255, 0, 0)');
  });
});
